// Intent router: pure greetings are answered statically and never reach
// the embedding model or the database.
const GREETING_PATTERN =
  /^\s*(hello|hi+|hey+|howdy|greetings)(\s+there)?[\s!.]*$|^\s*good\s+(morning|afternoon|evening)[\s!.]*$/i;

const STATIC_GREETING =
  "Hello, I'm Dr. Sara Hegy's coaching assistant. Ask me about a leadership " +
  'situation — delegation, difficult feedback, executive presence — and I ' +
  'will answer from documented coaching sessions.';

return $input.all().map((item) => {
  const message = String(
    item.json.message ?? item.json.chatInput ?? item.json.query ?? '',
  ).trim();
  const isGreeting = GREETING_PATTERN.test(message);
  return {
    json: {
      message,
      is_greeting: isGreeting,
      answer: isGreeting ? STATIC_GREETING : '',
    },
  };
});

// Extract the query embedding from the embedding HTTP response and keep
// the original question alongside it for the SQL node and the LLM node.
const routerItem = $('Greeting Router').first().json;

function extractEmbedding(json) {
  if (Array.isArray(json?.data?.[0]?.embedding)) return json.data[0].embedding;
  if (Array.isArray(json?.embeddings?.[0])) return json.embeddings[0];
  if (Array.isArray(json?.embedding)) return json.embedding;
  return null;
}

const embedding = extractEmbedding($input.first().json);

return [
  {
    json: {
      message: routerItem.message ?? '',
      query_vector: embedding ? `[${embedding.join(',')}]` : '[]',
      embedding_dims: embedding ? embedding.length : 0,
    },
  },
];

// Zero-match circuit breaker + context builder.
// Zero rows above the SQL thresholds -> short_circuit = true with the exact
// fallback sentence; the IF node downstream then answers directly and the
// LLM node is never executed.
const FALLBACK = 'No documented coaching frameworks match this topic.';

const rows = $input
  .all()
  .map((item) => item.json)
  .filter((row) => row && typeof row.content === 'string' && row.content.length > 0);

const frameworks = rows.filter((row) => row.stream_type === 'framework');
const voiceSamples = rows.filter((row) => row.stream_type === 'voice_sample');

if (rows.length === 0) {
  return [{ json: { short_circuit: true, answer: FALLBACK, context: '', match_count: 0 } }];
}

const render = (list) =>
  list
    .map((row) => `[${row.session_id} | similarity ${Number(row.similarity).toFixed(3)}]\n${row.content}`)
    .join('\n\n');

const context = [
  frameworks.length ? `FRAMEWORKS:\n${render(frameworks)}` : '',
  voiceSamples.length ? `VOICE SAMPLES (mirror this tone):\n${render(voiceSamples)}` : '',
]
  .filter(Boolean)
  .join('\n\n');

return [
  {
    json: {
      short_circuit: false,
      answer: '',
      context,
      match_count: rows.length,
      framework_count: frameworks.length,
      voice_sample_count: voiceSamples.length,
    },
  },
];

// Pull the assistant text out of an OpenAI-compatible / Ollama chat reply.
const json = $input.first().json;
const answer =
  json?.choices?.[0]?.message?.content ?? json?.message?.content ?? json?.response ?? '';
return [{ json: { answer: String(answer).trim() } }];
